arguments.command:
cd /tmp/vally-eval-trial-XkkMhM && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features $P/details/2026-10-06 $P/evidence/2026-10-06/discount tests/CheckoutPricing.UnitTest/Features/Discount
cat > $P/features/pricing-loyalty-discount.feature <<'E'
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  @loyalty-discount @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @loyalty-discount @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @loyalty-discount @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @loyalty-discount @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
E
cat > tests/CheckoutPricing.UnitTest/Features/Discount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Bronze customer is charged the Bronze price for a basket (AC-1)
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier loyaltyTier, int subtotalCents, int expectedChargedCents)
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, loyaltyTier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
E
dotnet build 2>&1 | tail -3
dotnet test --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $P/evidence/2026-10-06/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/2026-10-06/discount/acceptance-red.exit
git rev-parse HEAD > $P/evidence/2026-10-06/discount/acceptance-red.rev
cat $P/evidence/2026-10-06/discount/acceptance-red.exit; grep -iE "Expected|Actual|error|Failed" $P/evidence/2026-10-06/discount/acceptance-red.stdout | head

